(() => {
  'use strict';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = value => Array.isArray(value) ? value : [];
  const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
  const kindNames = {website:'网站',ppt:'演示文稿',document:'文档',project:'项目计划',code:'代码'};
  const statusNames = {running:'正在进行',queued:'等待开始',completed:'已完成',failed:'需要处理',interrupted:'已中断',paused:'已暂停',awaiting_approval:'等待确认',waiting_approval:'等待确认'};
  const tabs = {chats:'对话',requirements:'需求',tasks:'任务',artifacts:'产物',memory:'记忆'};
  let revision = 0, snapshot = null, library = [], selectedProject = '', projectTab = 'chats', flowFilter = 'all', artifactFilter = 'all';
  let flowSearch = '', selectedFlow = '', flowTab = 'overview';
  const pathKey = value => String(value || '').replace(/\\/g,'/').replace(/\/$/,'').toLowerCase();
  const titleForPath = value => String(value || '').split(/[\\/]/).filter(Boolean).at(-1) || '未关联项目';
  function savedProjects() { try { return list(JSON.parse(localStorage.getItem('gongming.project-bookmarks') || '[]')).filter(p => p && typeof p.path === 'string'); } catch { return []; } }
  async function request(url, body, method) {
    const response = await fetch(url,{method:method || (body === undefined ? 'GET':'POST'),headers:body === undefined?{Accept:'application/json'}:{'Content-Type':'application/json'},body:body === undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(30000)});
    const data = await response.json();if(!response.ok)throw new Error(data.message || data.error || '操作没有完成');return data;
  }
  const errorHtml = error => `<div class="navigation-error" role="alert">${esc(error.message)}<button class="text-link" data-navigation-refresh>重新读取</button></div>`;
  function modal(title,content) {
    const dialog=document.createElement('dialog');dialog.className='navigation-dialog';dialog.setAttribute('aria-label',title);
    dialog.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" class="icon-btn" data-navigation-close aria-label="关闭">×</button></header>${content}<p role="alert" class="navigation-form-error"></p>`;
    dialog.querySelector('[data-navigation-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();return dialog;
  }
  const date = value => {const timestamp=Date.parse(value);return Number.isFinite(timestamp)?new Date(timestamp).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'时间未记录';};
  const heading = (title,description,buttons='') => `<header class="navigation-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="button-row">${buttons}</div></header>`;
  const empty = (title,description,buttons='') => `<div class="navigation-empty"><span>✦</span><h2>${esc(title)}</h2><p>${esc(description)}</p>${buttons}</div>`;
  async function readStatus() {snapshot=await request('/api/status');return snapshot;}
  function projects() {
    const records=new Map();
    for(const item of savedProjects())records.set(pathKey(item.path),{key:pathKey(item.path),path:item.path,name:item.name||titleForPath(item.path),jobs:[]});
    const configured=snapshot?.config?.projectPath;if(configured&&!records.has(pathKey(configured)))records.set(pathKey(configured),{key:pathKey(configured),path:configured,name:titleForPath(configured),jobs:[]});
    for(const job of list(snapshot?.jobs)){const key=pathKey(job.projectPath)||'unlinked';if(!records.has(key))records.set(key,{key,path:job.projectPath||'',name:job.projectPath?titleForPath(job.projectPath):'未关联项目',jobs:[]});records.get(key).jobs.push(job);}
    return [...records.values()];
  }
  function projectRecord() {return projects().find(item=>item.key===selectedProject);}
  function sidebar(view) {
    const target=document.getElementById('sidebarContext');if(!target)return;
    target.hidden=!['projects','workflows'].includes(view);
    if(view==='projects')target.innerHTML=`<div class="sidebar-section-label">工作区<button class="text-link" data-project-add aria-label="添加项目">＋</button></div>${projects().map(project=>`<button class="sidebar-context-item ${project.key===selectedProject?'active':''}" data-project-key="${esc(project.key)}">${icon('folder')}<span>${esc(project.name)}</span><small>${project.jobs.length}</small></button>`).join('')||'<p>添加本地目录，集中查看工作。</p>'}`;
    if(view==='workflows')target.innerHTML=`<div class="sidebar-section-label">常用工作流<button class="text-link" data-flow-import aria-label="导入工作流">＋</button></div>${library.filter(flow=>flow.pinned).map(flow=>`<button class="sidebar-context-item" data-flow-run="${esc(flow.id)}"><span>${esc(flow.icon||'🔀')}</span><span>${esc(flow.name)}</span></button>`).join('')||'<p>在工作流卡片上点击 ☆，固定到这里。</p>'}<button class="text-link sidebar-workflow-import" data-flow-import>导入工作流</button>`;
  }
  function paintProjects(root) {
    const records=projects(),project=projectRecord();sidebar('projects');
    root.innerHTML=heading(project?project.name:'项目',project?project.path||'历史任务没有记录项目目录':'把同一目录的对话、需求和成果放在一起。',`<button class="outline-button" data-project-add>＋ 添加项目</button>${project?'<button class="primary-button" data-project-chat>新建项目对话</button>':''}`);
    if(!records.length){root.insertAdjacentHTML('beforeend',empty('给持续的工作一个位置','添加已有本地目录。代码开发需要已经提交过的 Git 仓库。','<button class="primary-button" data-project-add>添加项目目录</button>'));return;}
    if(!project){root.insertAdjacentHTML('beforeend',`<div class="navigation-card-grid">${records.map(item=>`<button class="navigation-card project-card" data-project-key="${esc(item.key)}"><span class="navigation-card-icon">📁</span><h2>${esc(item.name)}</h2><p>${esc(item.path||'未记录目录')}</p><small>${item.jobs.length} 个任务 · ${item.jobs.filter(j=>j.deliverable?.artifact).length} 份产物</small></button>`).join('')}</div>`);return;}
    root.insertAdjacentHTML('beforeend',`<nav class="navigation-tabs" aria-label="项目资源">${Object.entries(tabs).map(([key,title])=>`<button data-project-tab="${key}" aria-selected="${projectTab===key}">${title}</button>`).join('')}</nav><section id="projectResources" class="project-resources"></section>`);
    const body=root.querySelector('#projectResources'),jobs=project.jobs,ids=new Set(jobs.map(job=>job.id));
    if(projectTab==='tasks')body.innerHTML=jobs.length?jobs.map(jobCard).join(''):empty('还没有项目任务','在对话中说出目标，再交给总控安排。','<button class="outline-button" data-project-chat>新建项目对话</button>');
    if(projectTab==='artifacts')body.innerHTML=artifactCards(jobs.filter(job=>job.deliverable?.artifact));
    if(projectTab==='requirements'){
      const analyses=list(snapshot.analyses).filter(analysis=>jobs.some(job=>job.analysisId===analysis.id));
      body.innerHTML=`<div class="navigation-section-row"><p>仅显示与本项目任务明确关联的需求。</p><button class="outline-button" data-requirements="open">分析新需求</button></div>`+(analyses.length?analyses.map(analysis=>`<article class="navigation-card"><h2>${esc(analysis.brief)}</h2><p>${esc(analysis.result?.summary||'')}</p><ul>${list(analysis.result?.requirements).map(item=>`<li>${esc(item.text||item)}</li>`).join('')}</ul></article>`).join(''):empty('还没有关联需求','总控分析后的需求会随任务关联到这里。'));
    }
    if(projectTab==='memory'){
      const notes=jobs.flatMap(job=>list(job.tasks).filter(task=>task.id==='docs'&&task.status==='completed'&&task.result).map(task=>({job,task})));
      body.innerHTML='<p class="navigation-note">这里汇集已完成任务的文档与交接摘要；暂不代表模型拥有持续学习或全项目长期记忆。</p>'+(notes.length?notes.map(({job,task})=>`<article class="navigation-card"><h2>${esc(job.brief)}</h2><p>${esc(task.result.summary||JSON.stringify(task.result).slice(0,1200))}</p><button class="text-link" data-navigation-job="${esc(job.id)}">查看完整记录 →</button></article>`).join(''):empty('还没有可复用的交接记录','项目任务完成文档阶段后，相关摘要会显示在这里。'));
    }
    if(projectTab==='chats'){
      body.innerHTML='<p class="navigation-note" role="status">正在读取关联对话…</p>';
      request('/api/chats').then(data=>{if(!body.isConnected||selectedProject!==project.key||projectTab!=='chats')return;const chats=list(data.chats).filter(chat=>list(chat.jobIds).some(id=>ids.has(id)));body.innerHTML=chats.length?chats.map(chat=>`<button class="project-chat-row" data-navigation-chat="${esc(chat.id)}">${icon('chat')}<span><b>${esc(chat.title||'项目对话')}</b><small>${date(chat.updatedAt||chat.createdAt)}</small></span><i>↗</i></button>`).join(''):empty('从一段项目对话开始','完成任务关联后，对话会显示在这里。','<button class="outline-button" data-project-chat>新建项目对话</button>');}).catch(error=>{if(body.isConnected)body.innerHTML=errorHtml(error);});
    }
  }
  function jobCard(job){return `<article class="navigation-card navigation-job"><div><span>${esc(kindNames[job.kind]||'协作任务')}</span><small>${esc(statusNames[job.status]||job.status)}</small></div><h2>${esc(job.brief||'未命名任务')}</h2><p>${date(job.updatedAt||job.createdAt)}</p><button class="outline-button" data-navigation-job="${esc(job.id)}">${job.deliverable?.artifact?'审阅产物':'查看任务'}</button></article>`;}
  function artifactCards(jobs){return jobs.length?`<div class="navigation-card-grid">${jobs.map(job=>`<article class="navigation-card artifact-card"><span class="navigation-card-icon">${({website:'🌐',ppt:'📊',document:'📝',project:'📋',code:'⌘'})[job.kind]||'📦'}</span><span class="navigation-tag">${esc(kindNames[job.kind]||'文件')}</span><h2>${esc(job.deliverable.artifact.title||job.brief)}</h2><p>${esc(job.brief)}</p><small>${date(job.updatedAt||job.createdAt)} · ${esc(statusNames[job.status]||job.status)}</small><button class="outline-button" data-navigation-result="${esc(job.id)}">预览与审阅 →</button></article>`).join('')}</div>`:empty('产物会在这里汇合','完成网站、PPT 或文档工作流后，可以直接预览、批注和导出。','<button class="outline-button" data-view="workflows">选择工作流</button>');}
  function paintArtifacts(root){const jobs=list(snapshot?.jobs).filter(job=>job.deliverable?.artifact);root.innerHTML=heading('产物','集中预览、审阅和导出真实任务的成果。','<button class="outline-button" data-navigation-refresh>刷新</button>')+`<nav class="navigation-tabs" aria-label="筛选产物"><button data-artifact-filter="all" aria-selected="${artifactFilter==='all'}">全部 ${jobs.length}</button>${Object.entries(kindNames).map(([key,title])=>`<button data-artifact-filter="${key}" aria-selected="${artifactFilter===key}">${title}</button>`).join('')}</nav>`+artifactCards(jobs.filter(job=>artifactFilter==='all'||job.kind===artifactFilter));}
  function paintSettings(root){root.innerHTML=heading('设置','模型、协作方式与工具，在一个地方管理。')+`<div class="settings-hub-grid">${[
    ['models','🤝','模型连接','管理 API Key、订阅连接和本地模型，查看可用版本。'],
    ['assistants','🧭','助理与技能','查看常用技能，设置成员分工，导入自己的规范。'],
    ['mcp','🔌','插件与 MCP','连接外部工具，查看调用权限和执行记录。'],
    ['security','🛡️','安全与密钥','设置审批方式，了解本机密钥与文件安全。'],
    ['advanced','🛠️','高级工作台','完整任务看板、测试、Git、审批和审计记录。'],
    ['about','✦','关于 Resonance','本地多模型协作工作空间。']
  ].map(([key,emoji,title,description])=>`<button class="navigation-card settings-hub-card" data-settings-section="${key}"><span class="navigation-card-icon">${emoji}</span><div><h2>${title}</h2><p>${description}</p></div><span>›</span></button>`).join('')}</div><p class="navigation-note">密钥保存在本机。不同服务商独立计费；订阅是否可用取决于对应服务提供的连接方式。</p>`;}
  function paintAutomation(root){root.innerHTML=heading('自动化','自动运行需要可靠的调度与执行环境。')+empty('定时与事件触发尚未启用','当前版本支持手动运行工作流，尚未提供后台定时器。关闭应用后不会自动执行任务。','<button class="primary-button" data-view="workflows">手动运行工作流</button>')+'<div class="navigation-note">此页面不会创建虚假的定时规则或声称任务已安排。工作流的手动运行记录可以在详情页查看。</div>';}
  function flowCard(flow){return `<article class="navigation-card flow-card" data-flow-card="${esc(flow.id)}" draggable="true"><div class="flow-card-top"><span class="navigation-card-icon">${esc(flow.icon||'🔀')}</span><button type="button" class="flow-pin" data-flow-pin="${esc(flow.id)}" aria-label="${flow.pinned?'取消常用':'设为常用'}" aria-pressed="${!!flow.pinned}">${flow.pinned?'★':'☆'}</button></div><span class="navigation-tag">${esc(({builtin:'内置',imported:'已导入',custom:'自建'})[flow.source]||'工作流')}</span><h2>${esc(flow.name||flow.title)}</h2><p>${esc(flow.description)}</p><div class="flow-card-actions"><button class="primary-button" data-flow-run="${esc(flow.id)}">开始使用</button><button class="text-link" data-flow-details="${esc(flow.id)}">详情与记录</button></div></article>`;}
  function paintWorkflows(root){
    sidebar('workflows');const query=flowSearch.trim().toLocaleLowerCase(),items=library.filter(flow=>(flowFilter==='all'||flowFilter==='pinned'&&flow.pinned||flow.source===flowFilter)&&(!query||`${flow.name} ${flow.description}`.toLocaleLowerCase().includes(query)));
    root.innerHTML=heading('工作流','选一个做事的方法。填写需求后，总控安排协作并留下可审阅的成果。','<button class="outline-button" data-flow-import>导入工作流</button><button class="primary-button" data-flow-create>＋ 新建</button>')+`<div class="workflow-library-toolbar"><nav class="navigation-tabs" aria-label="筛选工作流">${[['all','全部'],['pinned','⭐ 常用'],['builtin','内置'],['imported','已导入'],['custom','自建']].map(([key,title])=>`<button data-flow-filter="${key}" aria-selected="${flowFilter===key}">${title}</button>`).join('')}</nav><input type="search" class="form-input" id="workflowLibrarySearch" placeholder="搜索工作流" aria-label="搜索工作流" value="${esc(flowSearch)}"></div><div class="navigation-card-grid workflow-library-grid">${items.map(flowCard).join('')}</div>${!items.length?empty('这里还没有工作流','切换分类，或导入一份 .gmflow.json 文件。','<button class="outline-button" data-flow-import>导入工作流</button>'):''}<p class="navigation-note">工作流不会携带密钥，也不会授权执行任意命令。拖动卡片可调整本机排序；右键查看管理选项。</p>`;
    root.querySelector('#workflowLibrarySearch').oninput=event=>{const input=event.currentTarget,start=input.selectionStart;flowSearch=input.value;paintWorkflows(root);const next=root.querySelector('#workflowLibrarySearch');next.focus();try{next.setSelectionRange(start,start);}catch{}};
  }
  async function reloadLibrary(){const data=await request('/api/workflow-library');library=list(data.workflows);return data;}
  async function runFlow(id){const flow=library.find(item=>item.id===id);if(!flow)return;const definition=flow.definition||{},fields=list(definition.inputs);
    const dialog=modal(`运行 · ${flow.name}`,`<p>${esc(flow.description)}</p><form id="libraryRunForm">${fields.map(field=>`<label>${esc(field.label)}${field.multiline?`<textarea name="${esc(field.key)}" rows="3" maxlength="20000" ${field.required?'required':''} placeholder="${esc(field.placeholder||'')}">${esc(field.default||'')}</textarea>`:`<input name="${esc(field.key)}" maxlength="20000" ${field.required?'required':''} placeholder="${esc(field.placeholder||'')}" value="${esc(field.default||'')}">`}</label>`).join('')}<div class="navigation-run-notice"><strong>运行前确认</strong><p>${flow.source==='imported'?'这是导入的工作流，请先检查输入和流程。':''}将使用你已连接的模型和当前团队分工；可能产生 API 费用。测试、Git 和外部工具遵循现有审批设置。</p><button class="text-link" type="button" data-manage-models>查看 / 添加模型</button></div><div class="button-row"><button class="outline-button" type="button" data-flow-details="${esc(id)}">先查看流程</button><button class="primary-button" type="submit">确认并开始</button></div></form>`);
    const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('[type=submit]');button.disabled=true;try{const prepared=await request(`/api/workflow-library/${encodeURIComponent(id)}/prepare`,{inputs:Object.fromEntries(new FormData(form))});dialog.close();await window.RuntimeUI.startTask({...prepared,kind:definition.trigger?.kind||'auto'});}catch(error){if(dialog.isConnected)dialog.querySelector('[role=alert]').textContent=error.message;}finally{button.disabled=false;}};
  }
  async function detailsFlow(id,tab='overview'){const flow=library.find(item=>item.id===id);if(!flow)return;selectedFlow=id;flowTab=tab;const definition=flow.definition||{};
    const dialog=modal(`${flow.icon||'🔀'} ${flow.name}`,`<nav class="navigation-tabs" aria-label="工作流详情">${[['overview','概览'],['pipeline','流程'],['inputs','输入'],['runs','运行记录'],['sharing','分享']].map(([key,title])=>`<button data-flow-detail-tab="${key}" aria-selected="${key===tab}">${title}</button>`).join('')}</nav><div id="flowDetailBody"></div><div class="button-row flow-detail-actions"><button class="text-link" data-flow-export="${esc(id)}">导出 JSON</button>${flow.source==='builtin'?'':`<button class="text-link" data-flow-edit="${esc(id)}">编辑</button><button class="text-link" data-flow-delete="${esc(id)}">删除</button>`}<button class="primary-button" data-flow-run="${esc(id)}">立即运行</button></div>`);
    dialog.querySelectorAll('[data-flow-detail-tab]').forEach(button=>button.onclick=()=>{dialog.close();detailsFlow(id,button.dataset.flowDetailTab);});const body=dialog.querySelector('#flowDetailBody');
    if(tab==='overview')body.innerHTML=`<p>${esc(flow.description)}</p><dl class="navigation-definition"><dt>来源</dt><dd>${esc(({builtin:'Resonance 内置',imported:'本机导入',custom:'本机创建'})[flow.source]||flow.source)}</dd><dt>版本</dt><dd>${esc(definition.version||'1.0.0')}</dd><dt>任务类型</dt><dd>${esc(kindNames[definition.trigger?.kind]||definition.trigger?.kind)}</dd><dt>作者</dt><dd>${esc(definition.author||'未填写')}</dd></dl><h3>提示词模板</h3><pre class="workflow-json">${esc(definition.trigger?.starterPrompt||'')}</pre>`;
    if(tab==='pipeline')body.innerHTML=`<p class="navigation-note">当前运行引擎使用依赖驱动的标准阶段；工作流自定义输入与目标，不执行导入的脚本或自定义阶段。</p><ol class="workflow-stage-list">${['总控分析需求','检索相关资料','制定架构方案','成员制作与修改','检查和测试','维护文档','回归验收','Git 与交付审阅'].map((label,index)=>`<li><b>${index+1}</b><span>${label}</span></li>`).join('')}</ol>`;
    if(tab==='inputs')body.innerHTML=list(definition.inputs).map(field=>`<article class="workflow-input-description"><b>${esc(field.label)}</b><span>${field.required?'必填':'选填'} · ${esc(field.key)}</span><p>${esc(field.placeholder||field.default||'运行时填写')}</p></article>`).join('');
    if(tab==='sharing')body.innerHTML='<h3>分享一份干净的工作流</h3><p>导出 JSON 文件后，可上传到自己的仓库或发给朋友。文件包含提示词与输入定义，请先检查是否含个人资料。</p><p class="navigation-note">尚未提供在线托管、二维码或远程分享链接。API Key 不会写入导出文件。</p>';
    if(tab==='runs'){body.textContent='正在读取运行记录…';try{await readStatus();if(!body.isConnected)return;const runs=list(snapshot.jobs).filter(job=>job.libraryWorkflowId===id||job.workflow?.libraryWorkflowId===id||(flow.source==='builtin'&&job.workflow?.id===definition.trigger?.kind&&!job.libraryWorkflowId));body.innerHTML=runs.length?runs.map(jobCard).join(''):empty('还没有运行记录','从这里启动工作流后，将按此工作流记录关联任务。');}catch(error){body.innerHTML=errorHtml(error);}}
  }
  function download(filename,value){const blob=new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function exportFlow(id){const flow=library.find(item=>item.id===id),definition=await request(`/api/workflow-library/${encodeURIComponent(id)}/export`);download(`${(flow?.name||'workflow').replace(/[<>:"/\\|?*]/g,'-')}.gmflow.json`,definition.definition||definition);}
  function editFlow(flow,initial){
    const definition=initial||flow?.definition||{format:'gongming-workflow@1',name:'我的工作流',icon:'📝',description:'说明这套流程适合做什么',version:'1.0.0',author:'',trigger:{kind:'document',starterPrompt:'请完成：{{description}}\n补充要求：{{requirements}}'},inputs:[{key:'description',label:'这次想完成什么',required:true,multiline:true},{key:'requirements',label:'补充要求',required:false,multiline:true}]};
    const dialog=modal(flow?'编辑工作流':'新建工作流',`<p>提示词中的 <code>{{description}}</code> 会替换为运行时输入。输入与流程定义为本机数据，不包含密钥。</p><form id="workflowEditor"><label>名称<input name="name" required maxlength="80" value="${esc(definition.name)}"></label><div class="wf-fields"><label>图标<input name="icon" maxlength="16" value="${esc(definition.icon||'📝')}"></label><label>任务类型<select name="kind">${Object.entries(kindNames).map(([key,title])=>`<option value="${key}" ${definition.trigger?.kind===key?'selected':''}>${title}</option>`).join('')}</select></label></div><label>简介<textarea name="description" maxlength="2000" rows="2">${esc(definition.description||'')}</textarea></label><label>提示词模板<textarea name="prompt" required maxlength="20000" rows="6">${esc(definition.trigger?.starterPrompt||'')}</textarea></label><details><summary>高级 · 输入定义 JSON</summary><textarea name="inputs" class="workflow-json-editor" rows="8" required>${esc(JSON.stringify(definition.inputs||[],null,2))}</textarea><p class="navigation-note">只接受说明和输入映射。不能声明任意命令、绕过审批或携带模型密钥。</p></details><div class="button-row"><button class="primary-button" type="submit">保存工作流</button></div></form>`);
    const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const next={...definition,name:form.elements.name.value,icon:form.elements.icon.value,description:form.elements.description.value,trigger:{...definition.trigger,kind:form.elements.kind.value,starterPrompt:form.elements.prompt.value},inputs:JSON.parse(form.elements.inputs.value)};await request(flow?`/api/workflow-library/${encodeURIComponent(flow.id)}`:'/api/workflow-library',{action:flow?'update':'create',definition:next});dialog.close();await reloadLibrary();window.Gongming.openView('workflows');}catch(error){dialog.querySelector('[role=alert]').textContent=error.message;}finally{button.disabled=false;}};
  }
  function importFlow(){const dialog=modal('导入工作流',`<p>选择 .gmflow.json 文件，或粘贴 <code>gongming-workflow@1</code> JSON。先保存为本机工作流，运行前仍会要求确认。</p><form><label class="workflow-import-file">选择本地文件<input type="file" accept=".json,.gmflow.json,application/json"></label><label>JSON 内容<textarea name="definition" rows="11" class="workflow-json-editor" required placeholder='{"format":"gongming-workflow@1", ...}'></textarea></label><p class="navigation-note">暂不从 URL 自动抓取文件。请下载后导入，以免不受信任的地址访问本机网络。</p><button class="primary-button" type="submit">校验并导入</button></form>`),form=dialog.querySelector('form');form.querySelector('[type=file]').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>256*1024)throw new Error('工作流 JSON 最多 256 KB');form.elements.definition.value=await file.text();}catch(error){dialog.querySelector('[role=alert]').textContent=error.message;}};form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await request('/api/workflow-library',{action:'import',definition:JSON.parse(form.elements.definition.value)});dialog.close();flowFilter='imported';await reloadLibrary();window.Gongming.openView('workflows');window.Gongming.toast('工作流已导入，运行前可查看完整输入和流程。');}catch(error){dialog.querySelector('[role=alert]').textContent=error.message;}finally{button.disabled=false;}};}
  function saveChatWorkflow(chat){if(!chat){window.Gongming.toast('先在当前对话中写下一个需求，再另存为工作流。');return;}const prompt=list(chat.messages).find(message=>message.role==='user')?.text||'';editFlow(null,{format:'gongming-workflow@1',name:chat.title||'对话工作流',icon:'💬',description:'根据对话中的需求创建；只保存提示词，不包含回复、附件和密钥。',version:'1.0.0',author:'',trigger:{kind:'document',starterPrompt:prompt+'\n\n本次需要：{{description}}'},inputs:[{key:'description',label:'本次想完成什么',required:true,multiline:true}]});}
  function addProject(){const dialog=modal('添加本地项目',`<form><label>项目名称<input name="name" maxlength="80" required placeholder="例如：我的网站"></label><label>本地目录的绝对路径<input name="path" required placeholder="C:\\Projects\\my-app"></label><p class="navigation-note">目录必须已经存在。这里只建立本机入口；不会创建文件或提交代码。代码任务需使用已有提交的 Git 仓库。</p><button class="primary-button" type="submit">添加项目</button></form>`),form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const result=await request('/api/config',{projectPath:form.elements.path.value.trim()}),path=result.config?.projectPath||result.projectPath||form.elements.path.value.trim(),records=savedProjects().filter(item=>pathKey(item.path)!==pathKey(path));records.unshift({name:form.elements.name.value.trim(),path});localStorage.setItem('gongming.project-bookmarks',JSON.stringify(records.slice(0,200)));selectedProject=pathKey(path);dialog.close();window.Gongming.openView('projects');}catch(error){dialog.querySelector('[role=alert]').textContent=error.message;}finally{button.disabled=false;}};}
  async function projectChat(){const project=projectRecord();window.Gongming.openView('chat');await window.ChatUI.prepareContext(project?.path?`项目：${project.name}\n本地目录：${project.path}\n\n请先和我确认这次要做的事。尚未读取目录；需要修改代码时请交给总控，并选择此项目目录。\n\n这次的目标：`:'这次的项目目标：');}
  async function openSettings(section){if(section==='models')return window.RuntimeUI.openSettings();if(section==='assistants')return window.Gongming.openView('extensions');if(section==='mcp'){window.Gongming.openView('extensions');setTimeout(()=>document.querySelector('[data-extension-tab=mcp]')?.click(),0);return;}if(section==='security')return window.PreferencesUI.open();if(section==='advanced')return window.Gongming.openView('runtime');if(section==='about')return modal('关于 Resonance','<p>在同一个本地工作空间里，对话、分工、制作与审阅。</p><p>支持多家 API 服务、本地模型和已支持的订阅连接。具体版本和连接能力可在模型连接中查看。</p><div class="button-row"><button class="outline-button" data-view="discover">查看工作空间总览</button><button class="outline-button" data-view="workspace">本地交互示例</button></div>');}
  async function render(view){sidebar(view);if(!['projects','workflows','artifacts','automation','settings'].includes(view))return;const root=document.getElementById(view+'View'),mine=++revision;if(!root)return;root.classList.add('navigation-page');if(view==='settings'){paintSettings(root);return;}if(view==='automation'){paintAutomation(root);return;}root.innerHTML='<p class="navigation-loading" role="status">正在读取本机记录…</p>';try{if(view==='workflows')await reloadLibrary();else await readStatus();if(mine!==revision||document.body.dataset.view!==view)return;if(view==='projects')paintProjects(root);if(view==='artifacts')paintArtifacts(root);if(view==='workflows')paintWorkflows(root);}catch(error){if(mine===revision&&root.isConnected)root.innerHTML=errorHtml(error);}}
  async function deleteFlow(id){const flow=library.find(item=>item.id===id);if(!flow||flow.source==='builtin')return;const dialog=modal('删除工作流？',`<p>删除“${esc(flow.name)}”的本机定义？已经创建的任务和产物会保留。</p><button class="primary-button" data-confirm-delete-flow>确认删除</button>`);dialog.querySelector('[data-confirm-delete-flow]').onclick=async event=>{event.target.disabled=true;try{await request(`/api/workflow-library/${encodeURIComponent(id)}`,undefined,'DELETE');dialog.close();await reloadLibrary();render('workflows');}catch(error){dialog.querySelector('[role=alert]').textContent=error.message;event.target.disabled=false;}};}
  document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
    if(button.hasAttribute('data-sidebar-toggle'))document.body.classList.toggle('chat-sidebar-open');
    if(button.hasAttribute('data-navigation-refresh'))render(document.body.dataset.view);
    if(button.dataset.settingsSection)openSettings(button.dataset.settingsSection);
    if(button.dataset.projectKey){selectedProject=button.dataset.projectKey;projectTab='chats';window.Gongming.openView('projects');}
    if(button.dataset.projectTab){projectTab=button.dataset.projectTab;paintProjects(document.getElementById('projectsView'));}
    if(button.hasAttribute('data-project-add'))addProject();if(button.hasAttribute('data-project-chat'))projectChat();
    if(button.dataset.navigationChat){window.Gongming.openView('chat');await window.ChatUI.render();window.ChatUI.openChat(button.dataset.navigationChat);}
    if(button.dataset.navigationJob){const job=list(snapshot?.jobs).find(item=>item.id===button.dataset.navigationJob);if(job?.deliverable?.artifact)window.WorkflowsUI.openResult(job.id);else window.Gongming.openView('runtime');}
    if(button.dataset.navigationResult)window.WorkflowsUI.openResult(button.dataset.navigationResult);
    if(button.dataset.artifactFilter){artifactFilter=button.dataset.artifactFilter;paintArtifacts(document.getElementById('artifactsView'));}
    if(button.dataset.flowFilter){flowFilter=button.dataset.flowFilter;paintWorkflows(document.getElementById('workflowsView'));}
    if(button.hasAttribute('data-flow-import'))importFlow();if(button.hasAttribute('data-flow-create'))editFlow();
    if(button.dataset.flowRun){button.closest('.navigation-dialog')?.close();runFlow(button.dataset.flowRun);}
    if(button.dataset.flowDetails){button.closest('.navigation-dialog')?.close();detailsFlow(button.dataset.flowDetails);}
    if(button.dataset.flowPin){const flow=library.find(item=>item.id===button.dataset.flowPin);await request(`/api/workflow-library/${encodeURIComponent(flow.id)}`,{action:'pin',pinned:!flow.pinned});await reloadLibrary();paintWorkflows(document.getElementById('workflowsView'));}
    if(button.dataset.flowExport)await exportFlow(button.dataset.flowExport);
    if(button.dataset.flowEdit){button.closest('.navigation-dialog')?.close();editFlow(library.find(item=>item.id===button.dataset.flowEdit));}
    if(button.dataset.flowDelete){button.closest('.navigation-dialog')?.close();deleteFlow(button.dataset.flowDelete);}
  }catch(error){window.Gongming?.toast(error.message);}});
  let dragging='';document.addEventListener('dragstart',event=>{const card=event.target.closest('[data-flow-card]');if(!card)return;dragging=card.dataset.flowCard;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',dragging);});
  document.addEventListener('dragover',event=>{if(dragging&&event.target.closest('[data-flow-card]'))event.preventDefault();});
  document.addEventListener('drop',async event=>{const card=event.target.closest('[data-flow-card]');if(!dragging||!card)return;event.preventDefault();const id=dragging;dragging='';if(id===card.dataset.flowCard)return;try{await request(`/api/workflow-library/${encodeURIComponent(id)}`,{action:'order',beforeId:card.dataset.flowCard});await reloadLibrary();paintWorkflows(document.getElementById('workflowsView'));}catch(error){window.Gongming.toast(error.message);}});document.addEventListener('dragend',()=>{dragging='';});
  document.addEventListener('contextmenu',event=>{const card=event.target.closest('[data-flow-card]');if(!card)return;event.preventDefault();detailsFlow(card.dataset.flowCard);});
  document.addEventListener('keydown',event=>{if(event.isComposing||document.querySelector('dialog[open]')||!event.altKey||event.ctrlKey||event.metaKey)return;if(event.key.toLowerCase()==='w'){event.preventDefault();window.Gongming.openView('workflows');}});
  window.NavigationUI=Object.freeze({render,saveChatWorkflow});
})();
